// ==UserScript==
//          Cursor Trial Link Generator (Fixed)
// :zh-CN   Cursor 试用链接生成器 (修正版)
//
//       1.1
//   Adds a button on the Cursor dashboard (all languages) to generate a trial checkout link.
// :zh-CN 在Cursor仪表盘页面（所有语言版本）添加一个按钮，用于一键生成试用订阅链接。
//        YourName
//
//
//         none
//
// ==/UserScript==(function() {
'use strict';// 创建一个函数来发送API请求
function generateTrialLink(tier) {
console.log(`[Cursor Script] Requesting trial link for tier: ${tier}`);
alert(`正在为 ${tier} 套餐生成试用链接...`);// 使用绝对路径以确保请求地址正确
fetch(' {
method: 'POST',
headers: {
'Content-Type': 'application/json',
'Accept': 'application/json'
},
// 浏览器会自动附加当前域的Cookie，所以不需要手动设置
body: JSON.stringify({
allowAutomaticPayment: true,
allowTrial: true,
tier: tier
})
})
.then(response => {
if (!response.ok) {
// 如果服务器返回错误，则抛出错误以便被catch捕获
return response.text().then(text => {
throw new Error(`服务器错误 (状态码: ${response.status}): ${text}`);
});
}
return response.json();
})
.then(data => {
console.log('[Cursor Script] Success:', data);
// 检查返回的是否是一个URL
if (typeof data === 'string' && data.startsWith('http')) {
alert(`成功获取链接！将为您在新标签页中打开。`);
// 在新标签页中打开获取到的Stripe链接
window.open(data, '_blank');
} else {
throw new Error('服务器返回的不是一个有效的URL。');
}
})
.catch((error) => {
console.error('[Cursor Script] Error:', error);
alert(`生成链接失败，请按 F12 打开控制台查看错误详情。\n错误: ${error.message}`);
});
}// 创建UI界面（一个包含三个按钮的面板）
function createUI() {
// 防止重复创建
if (document.getElementById('cursor-trial-panel')) return;const panel = document.createElement('div');
panel.id = 'cursor-trial-panel';
panel.style.position = 'fixed';
panel.style.bottom = '20px';
panel.style.right = '20px';
panel.style.backgroundColor = '#222';
panel.style.border = '1px solid #444';
panel.style.borderRadius = '8px';
panel.style.padding = '15px';
panel.style.zIndex = '9999';
panel.style.display = 'flex';
panel.style.flexDirection = 'column';
panel.style.gap = '10px';
panel.style.fontFamily = 'sans-serif';const title = document.createElement('h3');
title.textContent = '一键获取试用';
title.style.color = 'white';
title.style.margin = '0 0 10px 0';
title.style.textAlign = 'center';
title.style.fontSize = '16px';
panel.appendChild(title);const tiers = ['pro', 'pro_plus', 'ultra'];
tiers.forEach(tier => {
const button = document.createElement('button');
button.textContent = `获取 ${tier.charAt(0).toUpperCase() + tier.slice(1)} 试用`;
// 一些简单的样式
button.style.padding = '8px 12px';
button.style.cursor = 'pointer';
button.style.border = '1px solid #555';
button.style.borderRadius = '5px';
button.style.backgroundColor = '#333';
button.style.color = 'white';
button.style.fontSize = '14px';
button.onmouseover = () => button.style.backgroundColor = '#444';
button.onmouseout = () => button.style.backgroundColor = '#333';button.onclick = () => generateTrialLink(tier);
panel.appendChild(button);
});document.body.appendChild(panel);
console.log('[Cursor Script] UI panel created successfully.');
}// Cursor网站可能是个单页应用(SPA)，window.onload可能不够可靠。
// 我们使用一个定时器来检查页面是否已加载关键内容。
const interval = setInterval(() => {
// 通常dashboard页面会有一个特定的元素，这里我们简单检查body是否加载完成
// 更可靠的方法是检查一个特定的、迟于加载的元素
if (document.body) {
clearInterval(interval);
createUI();
}
}, 500);})();如果说你没有卡、手机号，或者脚本不生效怎么办？
